+// SPDX-License-Identifier: Apache-2.0
+
+use std::collections::BTreeMap;
+
+use fsl_core::{
+    FslValue, FsResolver, TraceAction, TraceChange, TraceStep, build_model, parse_kernel_source,
+};
+use fsl_runtime::replay_trace;
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let kernel = parse_kernel_source(
+        r"
+spec Replay {
+  type Bit = 0..1
+  state { x: Bit }
+  init { x = 0 }
+  action violate() { x = 1 }
+  action recover() { x = 0 }
+  invariant Safe { x == 0 }
+}
+",
+        &FsResolver::new("."),
+    )
+    .expect("parse model");
+    let model = build_model(kernel).expect("build model");
+    let initial = BTreeMap::from([("x".to_owned(), FslValue::Int(0))]);
+    let violated = BTreeMap::from([("x".to_owned(), FslValue::Int(1))]);
+    let trace = vec![
+        TraceStep {
+            step: 0,
+            state: initial.clone(),
+            action: None,
+            changes: BTreeMap::new(),
+        },
+        TraceStep {
+            step: 1,
+            state: violated,
+            action: Some(TraceAction {
+                name: "violate".to_owned(),
+                params: BTreeMap::new(),
+            }),
+            changes: BTreeMap::from([(
+                "x".to_owned(),
+                TraceChange {
+                    from: FslValue::Int(0),
+                    to: FslValue::Int(1),
+                },
+            )]),
+        },
+        TraceStep {
+            step: 2,
+            state: initial,
+            action: Some(TraceAction {
+                name: "recover".to_owned(),
+                params: BTreeMap::new(),
+            }),
+            changes: BTreeMap::new(),
+        },
+    ];
+
+    let error = replay_trace(model, &trace)
+        .expect_err("a trace must stop at its first violating transition");
+    assert!(
+        error.message.contains("continues after a violation"),
+        "{error}"
+    );
+}
